#if UNITY_EDITOR
using System;
using System.Collections.Generic;
using System.IO;
using UnityEditor;
using UnityEngine;

namespace ProjectSpark.Level104.AutoLayout.Editor
{
    public static class SparkL104URPPBRMaterialBuilder
    {
        public const string Output =
            "Assets/ProjectSpark/AutoGeneratedLevels/Level104/URP_PBR_Materials";

        private static readonly string[] Families =
        {
            "black", "ceramic", "chip", "copper", "core", "dielectric",
            "gold", "green", "mask", "pcb", "red", "resistor",
            "silver", "solder", "tin", "white"
        };

        private static readonly Dictionary<string, Material> Materials =
            new Dictionary<string, Material>(StringComparer.OrdinalIgnoreCase);

        [MenuItem("Tools/Project Spark/Automatic Level Generator/104/4. Rebuild URP PBR Materials")]
        public static void Rebuild()
        {
            string root = SparkL104FullLayoutBuilder.FindSourceRoot();
            if (string.IsNullOrEmpty(root))
            {
                Debug.LogError("[L104] Level104_MMX12 source kit was not found.");
                return;
            }
            if (BuildForRoot(root))
                Debug.Log("[L104] 16 URP PBR material families are ready.");
        }

        public static bool BuildForRoot(string root)
        {
            Materials.Clear();
            Shader shader = Shader.Find("Universal Render Pipeline/Lit");
            if (shader == null)
            {
                Debug.LogError("[L104] URP Lit shader is missing. Activate URP.");
                return false;
            }

            Directory.CreateDirectory(ToAbsolute(Output));
            AssetDatabase.Refresh();
            string textures = root + "/Textures";
            string packed = root + "/URP_Packed";

            for (int index = 0; index < Families.Length; index++)
            {
                string family = Families[index];
                string albedoPath = textures + "/" + family + "_Albedo.png";
                string normalPath = textures + "/" + family + "_Normal.png";
                string maskPath = packed + "/" + family + "_URP_MetallicSmoothness.png";
                string aoPath = packed + "/" + family + "_AO.png";

                if (!File.Exists(ToAbsolute(albedoPath)) ||
                    !File.Exists(ToAbsolute(normalPath)) ||
                    !File.Exists(ToAbsolute(maskPath)) ||
                    !File.Exists(ToAbsolute(aoPath)))
                {
                    Debug.LogError("[L104] Missing URP PBR textures for " + family);
                    return false;
                }

                ConfigureTexture(albedoPath, false, true);
                ConfigureTexture(normalPath, true, false);
                ConfigureTexture(maskPath, false, false);
                ConfigureTexture(aoPath, false, false);

                Texture2D albedo = AssetDatabase.LoadAssetAtPath<Texture2D>(albedoPath);
                Texture2D normal = AssetDatabase.LoadAssetAtPath<Texture2D>(normalPath);
                Texture2D metallic = AssetDatabase.LoadAssetAtPath<Texture2D>(maskPath);
                Texture2D occlusion = AssetDatabase.LoadAssetAtPath<Texture2D>(aoPath);
                if (albedo == null || normal == null || metallic == null || occlusion == null)
                {
                    Debug.LogError("[L104] Texture not imported yet: " + family);
                    return false;
                }

                string materialPath = Output + "/L104_" + family + ".mat";
                Material material = AssetDatabase.LoadAssetAtPath<Material>(materialPath);
                if (material == null)
                {
                    material = new Material(shader) { name = "L104_" + family };
                    AssetDatabase.CreateAsset(material, materialPath);
                }
                else if (material.shader != shader)
                {
                    material.shader = shader;
                }

                material.SetTexture("_BaseMap", albedo);
                material.SetColor("_BaseColor", Color.white);
                material.SetTexture("_MetallicGlossMap", metallic);
                material.SetFloat("_Metallic", 1f);
                material.SetFloat("_Smoothness", 1f);
                material.EnableKeyword("_METALLICSPECGLOSSMAP");
                material.SetTexture("_BumpMap", normal);
                material.SetFloat("_BumpScale", 1f);
                material.EnableKeyword("_NORMALMAP");
                material.SetTexture("_OcclusionMap", occlusion);
                material.SetFloat("_OcclusionStrength", 1f);
                material.SetFloat("_Surface", 0f);
                material.enableInstancing = true;
                EditorUtility.SetDirty(material);
                Materials.Add(family, material);
            }

            AssetDatabase.SaveAssets();
            return Materials.Count == Families.Length;
        }

        private static void ConfigureTexture(string assetPath, bool isNormal, bool srgb)
        {
            TextureImporter importer = AssetImporter.GetAtPath(assetPath) as TextureImporter;
            if (importer == null) return;
            TextureImporterType textureType =
                isNormal ? TextureImporterType.NormalMap : TextureImporterType.Default;
            if (importer.textureType == textureType && importer.sRGBTexture == srgb)
                return;
            importer.textureType = textureType;
            importer.sRGBTexture = srgb;
            importer.SaveAndReimport();
        }

        public static void BindAllMaterials(GameObject instance)
        {
            if (instance == null) return;
            EnsureCache();
            Renderer[] renderers = instance.GetComponentsInChildren<Renderer>(true);
            for (int r = 0; r < renderers.Length; r++)
            {
                Renderer renderer = renderers[r];
                Material[] assignments = renderer.sharedMaterials;
                bool changed = false;
                for (int m = 0; m < assignments.Length; m++)
                {
                    string family = IdentifyMaterial(assignments[m], renderer.transform);
                    Material replacement;
                    if (family != null && Materials.TryGetValue(family, out replacement))
                    {
                        assignments[m] = replacement;
                        changed = true;
                    }
                }
                if (changed) renderer.sharedMaterials = assignments;
            }
        }

        private static string IdentifyMaterial(Material assigned, Transform origin)
        {
            if (assigned != null)
            {
                string assignedName = assigned.name;
                if (assignedName.StartsWith("L104_", StringComparison.OrdinalIgnoreCase))
                    assignedName = assignedName.Substring(5);
                string match = MatchFamily(assignedName);
                if (match != null) return match;
            }
            const string separator = "__PSMAT__";
            for (Transform ancestor = origin; ancestor != null; ancestor = ancestor.parent)
            {
                string objectName = ancestor.name;
                int markerIndex = objectName.IndexOf(separator, StringComparison.OrdinalIgnoreCase);
                if (markerIndex < 0) continue;
                string taggedName = objectName.Substring(markerIndex + separator.Length);
                string familyMatch = MatchFamily(taggedName);
                if (familyMatch != null) return familyMatch;
            }
            return null;
        }

        private static string MatchFamily(string candidate)
        {
            if (Materials.ContainsKey(candidate)) return candidate;
            for (int i = 0; i < Families.Length; i++)
            {
                string family = Families[i];
                if (candidate.StartsWith(family + "_", StringComparison.OrdinalIgnoreCase) ||
                    candidate.StartsWith(family + " (", StringComparison.OrdinalIgnoreCase))
                    return family;
            }
            return null;
        }

        private static void EnsureCache()
        {
            if (Materials.Count == Families.Length) return;
            Materials.Clear();
            for (int i = 0; i < Families.Length; i++)
            {
                string family = Families[i];
                Material material = AssetDatabase.LoadAssetAtPath<Material>(
                    Output + "/L104_" + family + ".mat");
                if (material != null) Materials.Add(family, material);
            }
        }

        private static string ToAbsolute(string assetPath)
        {
            string project = Directory.GetParent(Application.dataPath).FullName;
            return Path.Combine(project, assetPath.Replace('/', Path.DirectorySeparatorChar));
        }
    }
}
#endif
